const D = { energy:.6, density:.5, scale:1, speed:1, hue:64, x:.5, y:.5, surge:.6, style:'cyanotype', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7) * 43758.5453; return s - Math.floor(s); };
const sty = P.style;
const EN = cl(P.energy,0,1), DN = cl(P.density,0,1), SC = cl(P.scale,.4,2.2);
const SG = cl(P.surge,0,1), AL = cl(P.alpha,0,100)/100;

if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
let dt = K.t - S.lastT; S.lastT = K.t;
if (!(dt >= 0) || dt > .25) dt = 1/60;
const SP = cl(P.speed,.05,4);
S.tt = (S.tt || 0) + dt*SP;
const T = S.tt;
// swell: a real wave train, incommensurate periods, so the surge never repeats
const swell = .85*Math.sin(T*.47) + .45*Math.sin(T*.79 + 1.3) + .28*Math.sin(T*1.21 + .4)
            + .3*Math.sin(T*.173);
const surge = (.3 + .95*EN)*SG*swell + A.lowmid*.7 + K.pulse*.18*K.intensity;
// THE CONVEYOR: the intercalary meristem extrudes tissue at the blade base while the
// distal tip erodes away. This phase only ever increases -> the piece cannot converge.
S.conv = (S.conv || 0) + dt*SP*(.055 + .075*EN);

const surf = cl(P.y - .42, -.2, .5);                        // sea surface, as a frame fraction
const floor2 = cl(P.y + .46, .55, 1.15);                    // rocky bottom

// ---- style ---------------------------------------------------------------
const H = P.hue;
let mode;
if (sty === 'plate') mode = 1; else if (sty === 'xray') mode = 2;
else if (sty === 'sonar') mode = 3; else mode = 0;          // 0 = cyanotype (Atkins' algae)

// ---- water column + light shafts ----------------------------------------
const bgKey = [width,height,sd,sty,H,surf,floor2].join('|');
if (!S.g || S.bgKey !== bgKey) {
  S.bgKey = bgKey;
  const bw = Math.min(560, Math.max(220, width|0));
  const bh = Math.max(1, Math.round(bw*height/Math.max(1,width)));
  const g = (S.g && S.g.width === bw && S.g.height === bh) ? S.g : createGraphics(bw, bh);
  S.g = g; g.colorMode(HSB, 360, 100, 100, 100);
  g.push(); g.noStroke();
  const sfy = bh*surf, fly = bh*floor2;
  for (let y=0;y<bh;y++){                                    // Beer's law: light dies with depth
    const v = cl((y - sfy)/Math.max(1, fly - sfy), 0, 1);
    const at = Math.exp(-v*1.9);
    if (mode === 1) g.fill(196 - v*8, 40 + v*18, 74*at + 9);
    else if (mode === 2) g.fill(194, 40, 10 + 9*at);
    else if (mode === 3) g.fill(250 - v*30, 62, 8 + 8*at);
    else g.fill(212 + v*4, 80 - v*6, 40*at + 8);
    g.rect(0, y, bw, 1.2); }
  for (let i=0;i<2400;i++){ g.fill(0, 0, mode===1 ? 40 : 92, 4 + fr(i*3.9)*7);
    g.rect(fr(i*2.7)*bw, fr(i*6.3+2)*bh, 1.5, 1.5); }
  g.noStroke();                                              // rocky bottom
  if (fly < bh) {
    g.fill(mode===1?28:(mode===3?258:214), mode===1?26:60, mode===2?14:12);
    g.rect(0, fly, bw, bh - fly + 2);
    for (let i=0;i<40;i++){ const rx = fr(i*5.1)*bw, rw = bw*(.03 + fr(i*2.3)*.11);
      g.fill(mode===1?26:(mode===3?254:216), mode===1?24:54, (mode===2?18:16) + fr(i*7.7)*10);
      g.ellipse(rx, fly + fr(i*3.3)*bh*.02, rw, rw*.42); }
  }
  const dc = g.drawingContext;
  const vg = dc.createRadialGradient(bw*.5, sfy, bw*.05, bw*.5, bh*.7, bw*.95);
  vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(0,0,0,0.4)');
  dc.fillStyle = vg; dc.fillRect(0, 0, bw, bh);
  g.pop();
  // light shafts stabbing through the canopy — drifts on its own rates
  const dw = 300, dh = Math.max(1, Math.round(dw*height/Math.max(1,width)));
  if (S.sh && S.sh.remove) S.sh.remove();
  const s2 = createGraphics(dw, dh);
  S.sh = s2; s2.colorMode(HSB, 360, 100, 100, 100);
  s2.push(); s2.clear(); s2.noStroke();
  for (let i=0;i<26;i++){
    const bx = fr(i*4.3)*dw, w2 = dw*(.006 + fr(i*2.7)*.03), sk = (fr(i*5.9)-.5)*.5;
    for (let k=0;k<4;k++){
      s2.fill(mode===3 ? 300 : (mode===1 ? 52 : 192), mode===1?22:16, 100, 2.6);
      s2.beginShape();
      s2.vertex(bx - w2*(1+k*.5), dh*surf); s2.vertex(bx + w2*(1+k*.5), dh*surf);
      s2.vertex(bx + w2*(3+k*1.4) + sk*dh, dh*1.02); s2.vertex(bx - w2*(3+k*1.4) + sk*dh, dh*1.02);
      s2.endShape(CLOSE);
    }
  }
  s2.pop();
}
image(S.g, 0, 0, width, height);
blendMode(mode === 1 ? SCREEN : ADD);
const shx = (Math.sin(T*.041) + .35*Math.sin(T*.0973 + 1.7))*width*.05;
tint(0, 0, 100, mode === 2 ? 26 : 44);
image(S.sh, -width*.06 + shx, 0, width*1.12, height);
noTint(); blendMode(BLEND);

// ---- sporophyte pool: recruit at the bottom, grow up, shed, drift out ----
const NMAX = 16;
const reseed = (k) => {
  const j = k.id*29.1 + (k.gen = (k.gen||0)+1)*17.3;
  k.xn = .04 + ((k.id*.6180339887) % 1)*.92 + (fr(j*1.3)-.5)*.05;   // golden-ratio spread
  k.z = .28 + fr(j*2.1)*.72;
  k.ph = fr(j*3.7)*6.28;
  k.vig = .74 + fr(j*4.3)*.55;
  k.nb = 6 + ((fr(j*5.9)*5)|0);                             // blades on this stipe
  k.hj = (fr(j*6.1)-.5)*26;
  k.life = 60 + fr(j*7.7)*50;
  k.sen = 16 + fr(j*8.3)*14;
  k.lean = (fr(j*9.1)-.5)*.5;
  k.age = 0;
};
if (!S.kp || S.kp.length !== NMAX || S.seedUsed !== sd) {
  S.seedUsed = sd; S.kp = [];
  for (let i=0;i<NMAX;i++){ const k = { id:i }; reseed(k); k.age = fr(i*13.1)*(k.life + k.sen); S.kp.push(k); }
}
for (let i=0;i<NMAX;i++){ const k = S.kp[i];
  k.age += dt*SP*(.6 + .7*EN)*(.7 + .5*K.intensity);
  if (k.age > k.life + k.sen) reseed(k); }

// ---- draw ----------------------------------------------------------------
const nDraw = Math.max(2, Math.round(3 + DN*13));
const order = [];
for (let i=0;i<nDraw;i++) order.push(i);
order.sort((a, b) => S.kp[a].z - S.kp[b].z);                // far planes first
if (mode === 2) blendMode(ADD);
strokeCap(ROUND); strokeJoin(ROUND);
const fy = floor2*height, sfy = surf*height;
const NV = 14;
const nC = nDraw <= 8 ? 7 : (nDraw <= 12 ? 5 : 3);          // conveyor detail, budgeted
const zCut = nDraw <= 10 ? .45 : .62;                       // far planes drop their corrugation

for (let oi=0; oi<nDraw; oi++) {
  const k = S.kp[order[oi]];
  const haze = .3 + .7*k.z;
  const grow = cl(k.age/26, 0, 1);
  const gr = grow*grow*(3 - 2*grow);
  const dead = k.age > k.life ? cl((k.age - k.life)/k.sen, 0, 1) : 0;
  const bx = (k.xn + (P.x - .5)*.5)*width;
  const topY = sfy + u*.03 + (1 - gr)*(fy - sfy)*.9;        // the canopy the stipe is reaching for
  const drift = dead*dead*width*.4*(k.id % 2 ? 1 : -1);     // shed stipes wash out of frame
  const alp = AL*(1 - dead*.8)*(.4 + .6*haze);
  if (alp < .02) continue;
  const hh = ((P.hue + k.hj + dead*40) % 360 + 360) % 360;
  const stW = u*.006*SC*k.vig*haze;

  // --- stipe: buoyant, taut, surge decaying exponentially with depth
  const SX = [], SY = [];
  for (let q=0;q<=NV;q++) {
    const v = q/NV;                                          // 0 holdfast .. 1 canopy
    const y = fy - (fy - topY)*v;
    const dep = cl((y - sfy)/Math.max(1, fy - sfy), 0, 1);   // 0 surface .. 1 bottom
    const orb = Math.exp(-dep*2.3);                          // orbital velocity dies with depth
    const sx = bx + drift
      + surge*u*.10*orb*k.vig*(.6 + .5*Math.sin(k.ph + T*.31))
      + Math.sin(T*(.83 + k.vig*.3) + k.ph + v*1.7)*u*.012*orb*(.3 + EN)
      + k.lean*u*.10*v*v + dead*u*.06*Math.sin(T*.7 + k.ph)*v;
    SX.push(sx); SY.push(y);
  }
  noFill();
  if (mode === 0) stroke(212, 20 - k.z*12, 88 + k.z*8, 88*alp);
  else if (mode === 1) stroke(30, 44, 24 + 14*k.z, 90*alp);
  else if (mode === 2) stroke(hh, 40, 66, 26*alp);
  else stroke(300 - k.z*60, 76, 60 + 30*k.z, 60*alp);
  strokeWeight(stW);
  beginShape(); for (let q=0;q<=NV;q++) vertex(SX[q], SY[q]); endShape();
  // --- holdfast gripping the rock
  if (gr > .05 && dead < .5) {
    strokeWeight(stW*.6);
    for (let q=0;q<5;q++){ const a2 = Math.PI*.5 + (q/4 - .5)*2.2;
      line(SX[0], SY[0], SX[0] + Math.cos(a2)*u*.022*SC*haze, SY[0] + Math.abs(Math.sin(a2))*u*.012*SC*haze); }
  }
  // --- blades + pneumatocysts along the stipe
  const nb = Math.round(k.nb*(.4 + .6*gr));
  for (let b=0;b<nb;b++) {
    const v = .16 + (b + .5)/Math.max(1,k.nb)*.82;
    const i2 = Math.min(NV, Math.round(v*NV));
    const px2 = SX[i2], py2 = SY[i2];
    const dep = cl((py2 - sfy)/Math.max(1, fy - sfy), 0, 1);
    const canopy = cl(1 - dep*4.2, 0, 1);                    // near the surface the blade lies flat
    const side = (b % 2) ? 1 : -1;
    const bl = u*.16*SC*k.vig*haze*(.55 + .45*gr)*(1 - dead*.3);
    const bw2 = bl*.17;
    const flap = Math.sin(T*(1.09 + (b%3)*.23) + k.ph + b*1.1)*(.1 + .3*EN);
    const ang = -Math.PI*.5*(1 - canopy*.86) + side*(.5 + .35*canopy) + surge*.30 + flap;
    push(); translate(px2, py2); rotate(ang);
    if (mode === 0) { noStroke(); fill(212, 6 + b*.5, 96 - b*.8, 80*alp); }
    else if (mode === 1) { stroke(28, 46, 16, 40*alp); strokeWeight(Math.max(.4, bl*.012));
      fill(hh, 52 - dead*26, (26 + 24*k.z)*(1 - dead*.2) + dead*20, 88*alp); }
    else if (mode === 2) { noStroke(); fill(hh, 44, 40, 15*alp); }
    else { noStroke(); fill(300 - k.z*60 - b*4, 80, 44 + 34*k.z, 42*alp); }
    beginShape(); vertex(0, 0);
    bezierVertex(bw2*1.5, bl*.16, bw2*1.15, bl*.72, 0, bl);
    bezierVertex(-bw2*1.15, bl*.72, -bw2*1.5, bl*.16, 0, 0);
    endShape(CLOSE);
    // THE CONVEYOR made visible: corrugations extrude at the base and vanish at the tip
    if (k.z > zCut && mode !== 2) {
      if (mode === 0) stroke(212, 34, 64, 52*alp);
      else if (mode === 1) stroke(hh, 40, 14 + 12*k.z, 46*alp);
      else stroke(304, 60, 96, 34*alp);
      strokeWeight(Math.max(.4, bl*.011)); noFill();
      for (let c=0;c<nC;c++) {
        let cv = ((c/nC) + S.conv*(.7 + .5*k.vig) + k.ph*.1) % 1;
        if (cv < 0) cv += 1;
        const fade2 = Math.min(1, cv*7) * Math.min(1, (1 - cv)*4.5);   // born at base, eroded at tip
        if (fade2 < .04) continue;
        const w3 = bw2*1.28*Math.sin(Math.PI*Math.pow(cv, .8))*.92;
        const yy = bl*cv;
        beginShape();
        vertex(-w3, yy - bl*.012); vertex(0, yy + bl*.016); vertex(w3, yy - bl*.012);
        endShape();
      }
      if (mode === 0) stroke(212, 30, 70, 40*alp); else if (mode === 1) stroke(hh, 44, 18, 40*alp);
      strokeWeight(Math.max(.4, bl*.014));
      line(0, 0, 0, bl*.96);                                  // midrib
    }
    pop();
    if (canopy < .55 && b % 2 === 0 && k.z > (nDraw <= 10 ? .3 : .55)) {   // gas bladder
      noStroke();
      if (mode === 0) fill(212, 10, 94, 76*alp); else if (mode === 1) fill(hh - 10, 40, 40 + 16*k.z, 90*alp);
      else if (mode === 2) fill(hh, 30, 60, 18*alp); else fill(310, 70, 80, 50*alp);
      push(); translate(px2, py2); rotate(ang*.5);
      ellipse(side*bl*.055, bl*.05, bl*.10, bl*.16); pop();
    }
  }
}
// ---- the surface itself: a bright rippling ceiling ------------------------
if (sfy > -height*.05) {
  blendMode(mode === 2 ? ADD : BLEND); noStroke();
  for (let q=0;q<3;q++){
    if (mode === 0) fill(206, 26, 96, 12*AL); else if (mode === 1) fill(196, 20, 96, 12*AL);
    else if (mode === 2) fill(190, 20, 80, 7*AL); else fill(292, 50, 90, 9*AL);
    rect(0, sfy - u*(.03 + q*.024) + Math.sin(T*.9 + q)*u*.004, width, u*(.03 + q*.024));
  }
  noFill(); strokeWeight(Math.max(1, u*.003));
  if (mode === 0) stroke(206, 14, 100, 44*AL); else if (mode === 3) stroke(292, 40, 100, 34*AL);
  else stroke(196, 12, 100, 44*AL);
  beginShape();
  for (let q=0;q<=26;q++){ const v = q/26;
    vertex(v*width, sfy + Math.sin(v*11 + T*1.7)*u*.008 + Math.sin(v*23 - T*2.3)*u*.004
           + surge*u*.008); }
  endShape();
}
// ---- marine snow: the forest is always shedding ---------------------------
noStroke();
const nSn = Math.round(14 + DN*30);
for (let q=0;q<nSn;q++) {
  const ph = fr(q*3.3)*6.28;
  const fv = ((T*(.014 + fr(q*5.7)*.022) + fr(q*7.1)) % 1);
  const sxx = (fr(q*2.3)*1.04 - .02)*width + Math.sin(T*.5 + ph)*u*.02 + surge*u*.03;
  const syy = sfy + fv*(fy - sfy);
  if (mode === 0) fill(212, 6, 96, 24*AL); else if (mode === 1) fill(44, 12, 88, 22*AL);
  else if (mode === 2) fill(190, 20, 70, 10*AL); else fill(296, 40, 92, 20*AL);
  ellipse(sxx, syy, u*.0028*SC, u*.0042*SC);
}
